h1
{font-size: 36px; line-height: 54px;}
h2
{font-size: 28px; line-height: 42px;}
h4
{font-size: 18px; line-height: 26px;font-weight: bold;}
h5
{font-size: 16px; line-height: 24px;}
a.wdjfy:link {color: #ffffff; text-decoration: none;font-size: 9px;} 
a.wdjfy:visited {color: #ffffff; text-decoration: none;font-size: 9px;} 
a.wdjfy:hover {color: #eeeeee;text-decoration: none;font-size: 9px;}
#footer-bottom {background-color: #206ab5; color: #ffffff;}

